"""
skill_gen.py
============
Auto-generates (creates or overwrites) a project-specific "signal catalog"
SKILL.md from live discovery of whatever CANoe project is CURRENTLY loaded.

PURPOSE
-------
This tooling (`.github/scripts/canoe/` + the CANoe Interface Agent) is
designed to be copied unmodified into any CANoe project. Hand-curated
project skills (e.g. `s3p-can-signals` for this workspace) give the richest,
most accurate signal catalog, but they don't exist yet for a brand-new
project. This module closes that gap automatically: it inspects the DBC
files and live SysVar namespace tree of whatever `.cfg` is currently open in
CANoe and writes out `.github/skills/canoe-project-signals/SKILL.md` --
always overwritten, never hand-edited -- so the tooling is immediately
useful on ANY project without manual authoring, and stays in sync if the
project's DBC/SysVars change.

This file is regenerated at the start of every session (see the CANoe
Interface Agent's workflow) via:
    python -m canoe skill generate

A hand-curated project skill, when present and accurate for the currently
loaded project, still takes priority over this auto-generated one -- see
"Project-Specific Skills" in the agent's instructions.

PUBLIC API
----------
  generate_signal_skill_md(conn, workspace_root) -> str   # markdown content
  write_signal_skill(conn, workspace_root, out_path=None) -> str  # path written
"""

from __future__ import annotations
import datetime
import os
from typing import Any, Dict, List, Optional

from .canoe_com import CANoeConnection


def _utc_now() -> str:
    return datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%d %H:%M:%S UTC")


# ---------------------------------------------------------------------------
# Live SysVar namespace tree walker
# ---------------------------------------------------------------------------

def _dump_namespace(ns_obj, depth: int, max_depth: int) -> Dict[str, Any]:
    node: Dict[str, Any] = {"variables": [], "children": {}}
    try:
        for i in range(1, ns_obj.Variables.Count + 1):
            var = ns_obj.Variables.Item(i)
            node["variables"].append(var.Name)
    except Exception:
        pass
    if depth < max_depth:
        try:
            children = ns_obj.Namespaces
            for i in range(1, children.Count + 1):
                child = children.Item(i)
                node["children"][child.Name] = _dump_namespace(child, depth + 1, max_depth)
        except Exception:
            pass
    return node


def dump_all_namespaces(conn: CANoeConnection, max_depth: int = 3) -> Dict[str, Any]:
    """Walk every top-level SysVar namespace up to `max_depth` levels deep."""
    tree: Dict[str, Any] = {}
    try:
        top = conn.system.Namespaces
        for i in range(1, top.Count + 1):
            ns = top.Item(i)
            tree[ns.Name] = _dump_namespace(ns, 1, max_depth)
    except Exception:
        pass
    return tree


def _render_tree_md(tree: Dict[str, Any], prefix: str = "") -> List[str]:
    lines: List[str] = []
    for name, node in tree.items():
        path = f"{prefix}::{name}" if prefix else name
        if node["variables"]:
            var_list = ", ".join(f"`{v}`" for v in node["variables"])
            lines.append(f"- **`{path}`** \u2014 variables: {var_list}")
        if node["children"]:
            lines.extend(_render_tree_md(node["children"], path))
    return lines


# ---------------------------------------------------------------------------
# Markdown generation
# ---------------------------------------------------------------------------

def generate_signal_skill_md(conn: CANoeConnection, workspace_root: str) -> str:
    from .dbc_reader import DBCReader
    from .discover import load_config

    cfg = load_config()
    cfg_path = cfg.get("canoe_config_path", "unknown")
    generated_utc = _utc_now()

    try:
        reader = DBCReader(workspace_root)
        messages = reader.list_messages()
    except Exception:
        messages = []

    tree = dump_all_namespaces(conn, max_depth=3)
    tree_lines = _render_tree_md(tree)

    msg_lines = [
        f"| `{m['name']}` | `{m['id']}` | {m['dlc']} | "
        f"{', '.join(f'`{s}`' for s in m['signals'])} |"
        for m in messages
    ]

    return f"""---
name: canoe-project-signals
description: "AUTO-GENERATED signal/SysVar catalog for the CURRENTLY loaded CANoe project ({cfg_path}). Regenerated by 'python -m canoe skill generate' -- do not hand-edit, changes will be overwritten. Use for discovering exact message/signal/SysVar names for THIS project before stimulating or reading the ECU."
argument-hint: "Describe the signal/DID you want to read or write for this project"
metadata:
  generated_utc: "{generated_utc}"
  source_config: "{cfg_path}"
  auto_generated: true
---

# Auto-Generated Signal Catalog

> **This file is regenerated automatically** -- the CANoe Interface Agent
> runs `python -m canoe skill generate` against whichever `.cfg` is
> currently loaded, at the start of every session. Do not hand-edit this
> file; edits are lost on the next regeneration. For curated, hand-written
> project knowledge, use a SEPARATE companion skill file instead (e.g.
> `s3p-can-signals` for this workspace, if present) -- a hand-curated
> project skill always takes priority over this generic dump when both
> exist for the same project.

Generated: {generated_utc}
Source CANoe config: `{cfg_path}`

## DBC Messages / Signals

| Message | ID | DLC | Signals |
|---|---|---|---|
{chr(10).join(msg_lines) if msg_lines else "_(no DBC files loaded -- run `python -m canoe dbc files` to check)_"}

Use `python -m canoe dbc signal <name>` for full metadata (factor/offset/min/max/unit/comment) on any signal above.

## Live SysVar Namespace Tree (depth 3)

{chr(10).join(tree_lines) if tree_lines else "_(no SysVar namespaces found -- is CANoe running with this project's .cfg loaded?)_"}

## How to use this catalog

1. Cross-reference a DBC message above against the SysVar tree to find the
   matching namespace (naming conventions vary by project -- look for a
   namespace whose name matches the message, or child `SYSVARS`/`TIMINGS`
   namespaces).
2. Read/write via:
   ```powershell
   python -m canoe signal sysvar read "<Namespace>" "<Variable>"
   python -m canoe signal sysvar write "<Namespace>" "<Variable>" <value>
   ```
3. If a sibling `TIMINGS` namespace exists next to the signal's namespace,
   check `EnableCyclic`/`MasterCyclicOnOff` -- if 0 (or absent), you likely
   need to write `SendOnce=1` to actually transmit the value onto the bus
   after writing the SysVar. If `EnableCyclic=1` already, the write
   propagates automatically on the next cyclic tick -- no extra trigger
   needed.
4. Verify via `python -m canoe signal bus read "<Message>" "<Signal>"`
   (works even with no SysVar link at all, for ECU Tx/feedback signals).
5. For multi-step/timed test cases, use
   `python -m canoe sequence ramp` / `sequence run-spec` (see the generic
   `canoe-interface` skill) instead of writing a new script per test case.
"""


def write_signal_skill(conn: CANoeConnection, workspace_root: str, out_path: Optional[str] = None) -> str:
    """Generate and write (create or overwrite) the auto-generated project skill file."""
    content = generate_signal_skill_md(conn, workspace_root)
    if out_path is None:
        out_path = os.path.join(workspace_root, ".github", "skills", "canoe-project-signals", "SKILL.md")
    os.makedirs(os.path.dirname(out_path), exist_ok=True)
    with open(out_path, "w", encoding="utf-8") as f:
        f.write(content)
    return out_path
